    final quotient = value ~/ divisor;
    final remainder = value % divisor;
    if (value < 0 && remainder != 0) return quotient - 1;
    return quotient;
  }

  static int _positiveMod(int value, int divisor) {
    return ((value % divisor) + divisor) % divisor;
