class BelovedVerses52Content {
  BelovedVerses52Content._();

  static MorningDevotionalItem forDate([
    DateTime? date,
    String languageCode = 'ko',
  ]) {
    final raw = date ?? DateTime.now();
    final day = DateTime(raw.year, raw.month, raw.day);
    final offset = day.difference(MorningDevotionalContent._cycleStart).inDays;
    final weekIndex = MorningDevotionalContent._positiveMod(
      MorningDevotionalContent._floorDiv(offset, 7),
      _references.length,
    );
    final localized = _itemForReference(
      _references[weekIndex],
    ).localized(languageCode);
    final code = MorningDevotionalLocalization.normalize(languageCode);
    return MorningDevotionalItem(
      themeName: _themeName(code),
      weekdayLabel: _weekLabel(code, weekIndex + 1),
      verse: localized.verse,
      reference: localized.reference,
      prayer: _prayerForWeek(weekIndex, code),
      translation: localized.translation,
      languageCode: localized.languageCode,
    );
  }

  static String _prayerForWeek(int weekIndex, String code) {
    final prayers = _prayersByLanguage[code] ?? _prayersByLanguage['en']!;
    return prayers[weekIndex % prayers.length];
  }

  static _MorningDevotionalDay _itemForReference(String reference) {
    for (final item in MorningDevotionalContent._belovedItems) {
      if (item.references['en'] == reference) return item;
    }
    return MorningDevotionalContent._belovedItems.first;
  }

  static String _themeName(String code) {
    return switch (code) {
      'ko' => '사랑받는 52구절',
      'de' => '52 geliebte Bibelverse',
      'ru' => '52 любимых стиха',
      'es' => '52 versículos amados',
      'pt' => '52 Versículos Amados',
      'zh' => '52句挚爱经文',
      'ja' => '愛される52の聖句',
      _ => '52 Beloved Verses',
    };
  }

  static String _weekLabel(String code, int week) {
    return switch (code) {
      'ko' => '$week주차 암송',
      'de' => 'Woche $week',
      'ru' => 'Неделя $week',
      'es' => 'Semana $week',
      'pt' => 'Semana $week',
      'zh' => '第$week周',
      'ja' => '第$week週',
      _ => 'Week $week',
    };
  }

