    ],
  };
}

class _MorningDevotionalDay {
  const _MorningDevotionalDay({
    required this.day,
    required this.week,
    required this.weekday,
    required this.weekdayLabels,
    required this.themes,
    required this.references,
    required this.verses,
    required this.prayers,
  });

  final int day;
  final int week;
  final String weekday;
  final Map<String, String> weekdayLabels;
  final Map<String, String> themes;
  final Map<String, String> references;
  final Map<String, String> verses;
  final Map<String, String> prayers;

  MorningDevotionalItem localized(String rawLanguageCode) {
    final code = MorningDevotionalLocalization.normalize(rawLanguageCode);
    final contentCode = verses.containsKey(code) && references.containsKey(code)
        ? code
        : 'en';
    return MorningDevotionalItem(
      themeName: themes[code] ?? themes['en']!,
      weekdayLabel: weekdayLabels[code] ?? weekdayLabels['en']!,
      verse: MorningDevotionalLocalization.withoutSuperscription(
        verses[contentCode] ?? verses['en']!,
      ),
      reference: references[contentCode] ?? references['en']!,
      prayer: prayers[code] ?? prayers['en']!,
      translation: MorningDevotionalLocalization.translationLabel(contentCode),
      languageCode: code,
    );
  }
}

class MorningDevotionalItem {
  const MorningDevotionalItem({
    required this.themeName,
    required this.weekdayLabel,
    required this.verse,
    required this.reference,
    required this.prayer,
    required this.translation,
    required this.languageCode,
  });

  final String themeName;
  final String weekdayLabel;
  final String verse;
  final String reference;
  final String prayer;
  final String translation;
  final String languageCode;
}

class MorningDevotionalLocalization {
  MorningDevotionalLocalization._();

  static final RegExp _leadingBracketedSuperscription = RegExp(
    r'^\s*(?:\[[^\]\r\n]*\]\s*)+',
  );
  static final RegExp _misplacedRussianSuperscription = RegExp(
    r'\s+Псалом Давида\.\s*Учение\.\s*$',
    caseSensitive: false,
  );

  static const supportedLanguages = <String>{
    "en",
    "ko",
    "de",
    "ru",
    "es",
    "pt",
    "zh",
    "ja",
  };

  static String normalize(String languageCode) {
    final code = languageCode.toLowerCase().split(RegExp('[-_]')).first;
    if (supportedLanguages.contains(code)) return code;
    return 'en';
  }

  /// Omits Psalm headings while preserving bracketed notes within a verse.
  static String withoutSuperscription(String rawText) {
    return rawText
        .replaceFirst(_leadingBracketedSuperscription, '')
        .replaceFirst(_misplacedRussianSuperscription, '')
        .trim();
  }

  static String translationLabel(String languageCode) {
    final code = normalize(languageCode);
    return _translationLabels[code] ?? _translationLabels['en']!;
  }

  static const Map<String, String> _translationLabels = {
    "en": "WEB",
    "ko": "개역한글",
    "de": "Elberfelder 1905",
    "ru": "Синодальный перевод",
    "es": "Sagradas Escrituras 1569",
    "pt": "Bíblia Livre",
    "zh": "和合本",
    "ja": "口語訳",
  };
}
